type IconName = keyof typeof ICONS;

type NodeSpec = {
  id: string;
  x: number;
  y: number;
  initialX?: number;
  initialY?: number;
  size: number;
  icon: IconName;
  start: number;
  ticks?: number;
  glow?: "strong" | "soft";
};

type EdgeSpec = {
  from: string;
  to: string;
  start: number;
  duration: number;
  dotted?: boolean;
};

type RaySpec = {
  from: string;
  toX: number;
  toY: number;
  start: number;
};

