const getLayoutProgress = (frame: number) =>
  interpolate(frame, [70, 292], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

const getPoint = (id: string, frame: number) => {
  const progress = getLayoutProgress(frame);
  if (NODE_MAP[id]) {
    const node = NODE_MAP[id];
    return {
      x: (node.initialX ?? node.x) + (node.x - (node.initialX ?? node.x)) * progress,
      y: (node.initialY ?? node.y) + (node.y - (node.initialY ?? node.y)) * progress,
    };
  }
  const hub = HUBS[id as keyof typeof HUBS];
  return {
    x: hub.initialX + (hub.x - hub.initialX) * progress,
    y: hub.y,
  };
};

