const ProgressLine: React.FC<{edge: EdgeSpec}> = ({edge}) => {
  const frame = useCurrentFrame();
  const from = getPoint(edge.from, frame);
  const to = getPoint(edge.to, frame);
  const progress = interpolate(
    frame,
    [edge.start, edge.start + edge.duration],
    [0, 1],
    {
      easing: Easing.inOut(Easing.cubic),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );

  if (progress <= 0) {
    return null;
  }

  const x2 = from.x + (to.x - from.x) * progress;
  const y2 = from.y + (to.y - from.y) * progress;

  return (
    <g>
      <line
        x1={from.x}
        y1={from.y}
        x2={x2}
        y2={y2}
        stroke="rgba(34,190,233,0.42)"
        strokeWidth={edge.dotted ? 3 : 11}
        strokeLinecap="round"
        strokeDasharray={edge.dotted ? "7 12" : undefined}
        filter="url(#lineGlow)"
      />
      <line
        x1={from.x}
        y1={from.y}
        x2={x2}
        y2={y2}
        stroke="rgba(240,252,255,0.92)"
        strokeWidth={edge.dotted ? 2 : 3.2}
        strokeLinecap="round"
        strokeDasharray={edge.dotted ? "7 12" : undefined}
      />
      <circle
        cx={x2}
        cy={y2}
        r={3.5 + 4 * (1 - progress)}
        fill="#dffbff"
        opacity={progress < 1 ? 0.9 : 0}
        filter="url(#lineGlow)"
      />
    </g>
  );
};

const PeripheralRay: React.FC<{ray: RaySpec}> = ({ray}) => {
  const frame = useCurrentFrame();
  const from = getPoint(ray.from, frame);
  const progress = interpolate(frame, [ray.start, ray.start + 32], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  if (progress <= 0) {
    return null;
  }

  return (
    <line
      x1={from.x}
      y1={from.y}
      x2={from.x + (ray.toX - from.x) * progress}
      y2={from.y + (ray.toY - from.y) * progress}
      stroke="rgba(235,251,255,0.75)"
      strokeWidth={2}
      strokeLinecap="round"
      strokeDasharray="3 8"
    />
  );
};

const MinorHub: React.FC<{hub: keyof typeof HUBS}> = ({hub}) => {
  const frame = useCurrentFrame();
  const spec = HUBS[hub];
  const point = getPoint(hub, frame);
  const progress = interpolate(frame, [spec.start, spec.start + 20], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  if (progress <= 0) {
    return null;
  }

  return (
    <div
      style={{
        position: "absolute",
        left: point.x - spec.size / 2,
        top: spec.y - spec.size / 2,
        width: spec.size,
        height: spec.size,
        borderRadius: "50%",
        border: "2px solid rgba(240,252,255,0.88)",
        background:
          "radial-gradient(circle at 35% 30%, rgba(228,250,255,0.96), rgba(47,171,208,0.74) 38%, rgba(7,28,48,0.9) 74%)",
        boxShadow:
          "0 0 20px rgba(57,210,248,0.62), inset 0 0 14px rgba(226,249,255,0.35)",
        transform: `scale(${0.68 + progress * 0.32})`,
        opacity: progress,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: spec.size * 0.32,
          border: "2px solid rgba(255,255,255,0.85)",
          transform: "rotate(45deg)",
        }}
      />
    </div>
  );
};

const NetworkNode: React.FC<{spec: NodeSpec}> = ({spec}) => {
  const frame = useCurrentFrame();
  const reveal = interpolate(frame, [spec.start, spec.start + 34], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const iconReveal = interpolate(
    frame,
    [spec.start + 11, spec.start + 31],
    [0, 1],
    {
      easing: Easing.out(Easing.cubic),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );

  if (reveal <= 0) {
    return null;
  }

  const ringRadius = spec.size / 2 - 7;
  const circumference = 2 * Math.PI * ringRadius;
  const pulse = Math.sin(clamp(reveal) * Math.PI);
  const haloStrength = spec.glow === "strong" ? 1 : spec.glow === "soft" ? 0.68 : 0.48;
  const tickCount = spec.ticks ?? 0;
  const tickAngles = Array.from({length: tickCount}, (_, index) => {
    const base = -112 + (index * 360) / Math.max(1, tickCount);
    return base + ((spec.start * 17 + index * 37) % 31) - 15;
  });

  return (
    <div
      style={{
        position: "absolute",
        left: spec.x - spec.size / 2 - 30,
        top: spec.y - spec.size / 2 - 30,
        width: spec.size + 60,
        height: spec.size + 60,
        opacity: reveal,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 30,
          borderRadius: "50%",
          transform: `scale(${0.82 + iconReveal * 0.18})`,
          background:
            "radial-gradient(circle at 35% 27%, rgba(210,246,255,0.34) 0%, rgba(24,102,133,0.34) 28%, rgba(6,25,46,0.90) 72%, rgba(2,14,27,0.98) 100%)",
          border: "1px solid rgba(229,250,255,0.58)",
          boxShadow: `0 0 ${22 + pulse * 38}px rgba(55,214,255,${0.25 + 0.34 * haloStrength}), inset 0 0 28px rgba(86,207,235,0.20)`,
        }}
      />

      <svg
        width={spec.size + 60}
        height={spec.size + 60}
        viewBox={`0 0 ${spec.size + 60} ${spec.size + 60}`}
        style={{
          position: "absolute",
          inset: 0,
          overflow: "visible",
          filter: "drop-shadow(0 0 9px rgba(104,226,255,0.78))",
        }}
      >
        {tickAngles.map((angle, index) => {
          const radians = (angle * Math.PI) / 180;
          const center = spec.size / 2 + 30;
          const inner = spec.size / 2 + 10;
          const outer = inner + 17 + (index % 2) * 7;
          const tickReveal = interpolate(reveal, [0.55, 1], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          return (
            <line
              key={angle}
              x1={center + Math.cos(radians) * inner}
              y1={center + Math.sin(radians) * inner}
              x2={center + Math.cos(radians) * (inner + (outer - inner) * tickReveal)}
              y2={center + Math.sin(radians) * (inner + (outer - inner) * tickReveal)}
              stroke="rgba(238,253,255,0.92)"
              strokeWidth={2.5}
              strokeLinecap="round"
            />
          );
        })}
        <circle
          cx={spec.size / 2 + 30}
          cy={spec.size / 2 + 30}
          r={ringRadius}
          fill="none"
          stroke="rgba(81,209,243,0.32)"
          strokeWidth={14}
          strokeDasharray={circumference}
          strokeDashoffset={circumference * (1 - reveal)}
          transform={`rotate(-90 ${spec.size / 2 + 30} ${spec.size / 2 + 30})`}
        />
        <circle
          cx={spec.size / 2 + 30}
          cy={spec.size / 2 + 30}
          r={ringRadius}
          fill="none"
          stroke="#f1fdff"
          strokeWidth={5.5}
          strokeLinecap="round"
          strokeDasharray={circumference}
          strokeDashoffset={circumference * (1 - reveal)}
          transform={`rotate(-90 ${spec.size / 2 + 30} ${spec.size / 2 + 30})`}
        />
        <circle
          cx={spec.size / 2 + 30}
          cy={spec.size / 2 + 30}
          r={ringRadius + 9}
          fill="none"
          stroke="rgba(194,247,255,0.78)"
          strokeWidth={2}
          strokeLinecap="round"
          strokeDasharray={`${circumference * 0.22} ${circumference * 0.78}`}
          strokeDashoffset={circumference * (1 - reveal) * 0.86}
          transform={`rotate(-138 ${spec.size / 2 + 30} ${spec.size / 2 + 30})`}
          opacity={0.55 + pulse * 0.45}
        />
      </svg>

      <Img
        src={ICONS[spec.icon]}
        style={{
          position: "absolute",
          left: 30 + spec.size * 0.11,
          top: 30 + spec.size * 0.11,
          width: spec.size * 0.78,
          height: spec.size * 0.78,
          objectFit: "contain",
          opacity: iconReveal,
          transform: `scale(${0.74 + iconReveal * 0.26})`,
          filter:
            "saturate(1.12) contrast(1.04) drop-shadow(0 0 10px rgba(104,226,255,0.48))",
        }}
      />

      <div
        style={{
          position: "absolute",
          left: 30 + spec.size * 0.22,
          right: 30 + spec.size * 0.22,
          top: 30 + spec.size * 0.08,
          height: spec.size * 0.17,
          borderRadius: "50%",
          background:
            "radial-gradient(ellipse, rgba(232,253,255,0.42), rgba(232,253,255,0) 72%)",
          opacity: iconReveal * 0.8,
          mixBlendMode: "screen",
        }}
      />
    </div>
  );
};

const NetworkRig: React.FC = () => {
  const frame = useCurrentFrame();
  const rigProgress = interpolate(frame, [9, 292], [0, 1], {
    easing: Easing.out(Easing.quad),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const rigScale = 1.55 + (1 - 1.55) * rigProgress;
  const rigX = 222 * (1 - rigProgress);
  const rigY = -10 * (1 - rigProgress);

  return (
    <AbsoluteFill
      style={{
        transform: `translate3d(${rigX}px, ${rigY}px, 0)`,
        transformOrigin: "0 0",
      }}
    >
      <AbsoluteFill
        style={{
          transform: `scale(${rigScale})`,
          transformOrigin: `${ANCHOR_X}px ${ANCHOR_Y}px`,
        }}
      >
        <svg
          width={DESIGN_WIDTH}
          height={DESIGN_HEIGHT}
          viewBox={`0 0 ${DESIGN_WIDTH} ${DESIGN_HEIGHT}`}
          style={{position: "absolute", inset: 0, overflow: "visible"}}
        >
          <defs>
            <filter id="lineGlow" x="-30%" y="-30%" width="160%" height="160%">
              <feGaussianBlur stdDeviation="5" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>
          {EDGES.map((edge, index) => (
            <ProgressLine key={`${edge.from}-${edge.to}-${index}`} edge={edge} />
          ))}
          {RAYS.map((ray, index) => (
            <PeripheralRay key={`${ray.from}-${index}`} ray={ray} />
          ))}
        </svg>

        <MinorHub hub="leftHub" />
        {NODES.map((node) => {
          const point = getPoint(node.id, frame);
          return <NetworkNode key={node.id} spec={{...node, ...point}} />;
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

